type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // shape has exactly 2 entries: R, C, both positive
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    let len = a.len();

    // By problem assumption, len == r or len == c
    // If len == r -> broadcast as column vector:
    // each matrix[i][j] = a[i]
    // else len == c -> broadcast as row vector:
    // each matrix[i][j] = a[j]

    if len == r {
        // a is column vector
        // For each row i, fill row with a[i]
        (0..r).map(|i| vec![a[i]; c]).collect()
    } else {
        // a is row vector (len == c)
        // For each row, clone a
        (0..r).map(|_| a.clone()).collect()
    }
}